/* getApTaxBillNo_v2 */ 
SELECT	IVDT.AP_TAX_BILL_NO
FROM	ICOMIVDT IVDT
WHERE	IVDT.BUYER = #{BUYER}
AND		IVDT.INV_NO = #{INV_NO}
AND		IVDT.INV_SEQ = #{INV_SEQ}
AND		IVDT.STATUS <> 'D'


/* getApTaxBillNoWms_v2 */ 
SELECT	IVDT.AP_TAX_BILL_NO
FROM	ICOMIVDT IVDT
WHERE	(BUYER,INV_NO,INV_SEQ) = (
	SELECT BUYER,S_INV_NO,S_INV_SEQ FROM WMSIVDT WMS
	WHERE	WMS.BUYER = #{BUYER}
	AND		WMS.INV_NO = #{INV_NO}
	AND		WMS.INV_SEQ = #{INV_SEQ}
	AND		WMS.STATUS <> 'D'
)
AND IVDT.STATUS <> 'D'

