FROM CAR_STOCK_GRDT CAR
WHERE CAR.BUYER = #{BUYER}
AND CAR.GR_NO = #{GR_NO}
AND CAR.GR_SEQ = TO_CHAR(#{GR_SEQ},'FM000000')
AND STATUS != 'D'


/*selectMasterMpSoGrDetailCarStockCheckQty*/
SELECT
	(GR_QTY-IV_QTY)-#{GR_QTY} AS CHECK_QTY
FROM CAR_STOCK
WHERE BUYER = #{BUYER}
AND BUYER_ITEM_NO = #{BUYER_ITEM_NO}

