/*updateMasterMpSoGrDetailCarStockMinus*/
UPDATE CAR_STOCK SET
GR_QTY = (GR_QTY-#{GR_QTY})
,CHANGE_USER_ID = #{st_user_id}
,CHANGE_DATE = SYSDATE
WHERE BUYER = #{BUYER}
AND BUYER_ITEM_NO = #{BUYER_ITEM_NO}


/*updateMasterMpSoGrDetailCarStockGrdt*/
