STATUS = 'D'
,CHANGE_USER_ID = #{st_user_id}
,CHANGE_DATE = SYSDATE
WHERE BUYER = #{BUYER}
AND BUYER_ITEM_NO = #{BUYER_ITEM_NO}
AND GR_NO = #{GR_NO}
AND GR_SEQ = #{GR_SEQ}
AND STATUS != 'D'
